// swift-tools-version: 6.3
// The swift-tools-version declares the minimum version of Swift required to build this package.

import PackageDescription

let package = Package(
    name: "uitest-probe",
    products: [
        // Products define the executables and libraries a package produces, making them visible to other packages.
        .library(
            name: "uitest-probe",
            targets: ["uitest-probe"]
        ),
    ],
    targets: [
        // Targets are the basic building blocks of a package, defining a module or a test suite.
        // Targets can depend on other targets in this package and products from dependencies.
        .target(
            name: "uitest-probe"
        ),

import Testing
@testable import uitest_probe

@Test func example() async throws {
    // Write your test here and use APIs like `#expect(...)` to check expected conditions.
    // Swift Testing Documentation
    // https://developer.apple.com/documentation/testing
}

input.patchText:
*** Begin Patch
*** Add File: /private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/bench-cfg-none-6cg5lus4/uitest-probe/Tests/uitest-probeTests/FeedTabUITests.swift
+import XCTest
+
+final class FeedTabUITests: XCTestCase {
+    func testOpenFeedsTab() throws {
+        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
+        let alert = springboard.alerts.element(boundBy: 0)
+        if alert.waitForExistence(timeout: 5) {
+            alert.buttons["Open"].tap()
+        }
+
+        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
+        app.activate()
+
+        let feedsTab = app.buttons["Feeds"]
+        if feedsTab.waitForExistence(timeout: 10) {
+            feedsTab.tap()
+        }
+
+        XCTAssertTrue(app.staticTexts["Discover New Feeds"].waitForExistence(timeout: 10))
+    }
+}
*** End Patch

